package com.tekwatt.ocpp.service;import com.fasterxml.jackson.databind.*;import com.fasterxml.jackson.databind.node.*;import com.tekwatt.ocpp.dto.FirmwareCommandRequest;import java.util.UUID;import org.springframework.http.HttpStatus;import org.springframework.stereotype.Service;import org.springframework.web.server.ResponseStatusException;@Service public class OcppCommandService{private final ConnectionRegistry registry;private final OcppAuditService audit;private final ObjectMapper json;public OcppCommandService(ConnectionRegistry r,OcppAuditService a,ObjectMapper j){registry=r;audit=a;json=j;}public String firmware(FirmwareCommandRequest r){String protocol;try{protocol=registry.protocol(r.stationId());}catch(IllegalStateException e){throw new ResponseStatusException(HttpStatus.CONFLICT,e.getMessage());}if(!r.ocppVersion().equals(protocol))throw new ResponseStatusException(HttpStatus.CONFLICT,"Connected charger negotiated "+protocol);String uid=UUID.randomUUID().toString();ObjectNode payload=json.createObjectNode();if("ocpp1.6".equals(protocol)){payload.put("location",r.location()).put("retrieveDate",r.retrieveDate().toString()).put("retries",3).put("retryInterval",60);}else{payload.put("requestId",Math.abs(r.jobId().hashCode()));ObjectNode firmware=payload.putObject("firmware");firmware.put("location",r.location()).put("retrieveDateTime",r.retrieveDate().toString());if(r.signature()!=null)firmware.put("signature",r.signature());}ArrayNode frame=json.createArrayNode().add(2).add(uid).add("UpdateFirmware").add(payload);String text=frame.toString();try{registry.send(r.stationId(),text);audit.record(r.stationId(),"OUT",2,uid,"UpdateFirmware",text);}catch(Exception e){throw new ResponseStatusException(HttpStatus.BAD_GATEWAY,"Could not send OCPP command");}return uid;}}
